import pandas as pd

def clean(df):
    df = df.drop_duplicates()
    category_map = {
        'accessories': 'Accessories',
        'office supplies': 'Office Supplies',
        'Furnture': 'Furniture'
    }
    df['Category'] = df['Category'].replace(category_map)
    return df

def answer(df):
    counts = df.groupby('Category').size()
    return counts.to_dict()
